<?php require_once "config.php";require_login();$text=trim($_POST['inci']??'');$all=db()->query("SELECT * FROM ingredients ORDER BY name");$found=[];$low=strtolower($text);while($i=$all->fetch_assoc()){if(strpos($low,strtolower($i['name']))!==false)$found[]=$i;}if(!$found):?><div class="notice">Belum ada ingredients yang cocok di database lokal. Coba nama INCI yang umum seperti Niacinamide, Glycerin, Hyaluronic Acid, Salicylic Acid, Ceramide NP, atau Retinol.</div><?php else:?><div class="analysis-box"><h3>Detected <?=count($found)?> ingredients</h3><?php foreach($found as $i):?><div class="analysis-item"><b><?=e($i['name'])?></b><span><?=e($i['function_text'])?></span><small><?=e($i['benefits'])?></small><em class="<?=$i['rating']==='Caution'?'warn':''?>"><?=e($i['rating'])?></em></div><?php endforeach;?></div><?php endif;
$st=db()->prepare("INSERT INTO scan_history(user_id,raw_text) VALUES(?,?)");$uid=$_SESSION['user_id']; $st->bind_param("is",$uid,$text);$st->execute(); ?>